def qa(i):
 base=[('gist','ما الفكرة المركزية؟','أن الحكم المتقدم يتطلب إعادة بناء الادعاء ومقدماته وآلياته وحدود الأدلة قبل تقييمه.'),('literal_detail','ما نوعان من الأدلة أو الطبقات اللذان يقارنهما النص؟','يقارن بين مصادر أو قواعد أو نماذج أو آليات مختلفة بحسب passage.'),('inference','لماذا لا يكفي وصف واحد مثل عادل أو دقيق أو مقنع؟','لأن الوصف لا يحدد معيار التطبيق ولا الآلية ولا توزيع الخطأ.'),('argument_relation','ما وظيفة التفسير المنافس؟','اختبار ما إذا كان الدليل يميز الحجة المفضلة عن بديل معقول.'),('main_claim','ما الذي يجعل الحكم أقوى؟','إعلان معاييره وربطه بأدلة تواجه البدائل والآثار غير المرئية.'),('contrast','ما الفرق بين وجود معلومة ووظيفتها في الحجة؟','المعلومة قد تكون صحيحة، لكن قوتها تعتمد على الادعاء الذي تستخدم لدعمه.'),('inference','لماذا تهم قابلية المراجعة؟','لأنها تسمح بكشف الخطأ وتصحيح القرار بدل تثبيته رغم تغير الأدلة.'),('summary','ما المهارة المشتركة بين مجالات النص؟','إعادة بناء العلاقة بين الادعاء والدليل والآلية والبدائل.'),('inference','كيف يتعامل القارئ مع عدم الحسم؟','يحدد ما بقي مجهولًا من دون مساواة كل التفسيرات.'),('inference','ما معيار النجاح في هذا المستوى؟','تفسير أدق وأوسع للأدلة مع افتراضات معلنة وقدرة على مواجهة الاعتراضات.')]
 q=[];a=[]
 for j,(typ,p,x) in enumerate(base,1):q.append({'id':f'q{j}','type':typ,'prompt':p,'answer_id':f'a{j}','target_ids':[]});a.append({'id':f'a{j}','question_id':f'q{j}','answer':x,'explanation':''})
 return q,a
